while (NS_SUCCEEDED(enumerator->GetNext(getter_AddRefs(supports))) &&
       supports) {
  card = do_QueryInterface(supports);

  card->GetIsMailList(&isMailList);
  if (isMailList) {
    continue;
  }

  uint32_t rowId;
  card->GetPropertyAsUint32(kRowIDProperty, &rowId);
  cardMap.InsertOrUpdate(rowId, card);
